func (i *Index) location(position token.Pos) location {
	value := i.files.Position(position)
	return location{
		file:   value.Filename,
		line:   value.Line,
		column: value.Column,
	}
}

func (i *Index) nodeSpan(start token.Pos, stop token.Pos) span {
	return span{start: i.location(start), stop: i.location(stop)}
}
